// lessonSchema.ts

/**
 * schemas/lessonSchema.ts
 *
 * Defines the schema for structured lesson outputs.
 *
 * Responsibilities:
 * - Enforce hierarchical consistency for lessons.
 * - Validate JSON outputs generated by the OpenAI API against this schema.
 *
 * Dependencies:
 * - Zod for schema definition and validation.
 * - Used in `aiService.ts` for validating responses.
 */

export const lessonSchema = {
  "name": "study_notes",
  "strict": true,
  "schema": {
    "type": "object",
    "$defs": {
      "slide": {
        "type": "object",
        "required": [
          "title",
          "text"
        ],
        "properties": {
          "text": {
            "type": "string",
            "description": "The content or text of the slide."
          },
          "title": {
            "type": "string",
            "description": "The title of the slide."
          }
        },
        "description": "A slide containing title and text for documentation.",
        "additionalProperties": false
      },
      "concept": {
        "type": "object",
        "required": [
          "title",
          "content"
        ],
        "properties": {
          "title": {
            "type": "string",
            "description": "The title of the concept."
          },
          "content": {
            "type": "array",
            "items": {
              "$ref": "#/$defs/slide"
            },
            "description": "Slides that document the content of the concept."
          }
        },
        "description": "A concept related to a subtopic, containing its title and content.",
        "additionalProperties": false
      },
      "subtopic": {
        "type": "object",
        "required": [
          "title",
          "content",
          "concept_bank"
        ],
        "properties": {
          "title": {
            "type": "string",
            "description": "The title of the subtopic."
          },
          "content": {
            "type": "array",
            "items": {
              "$ref": "#/$defs/slide"
            },
            "description": "Slides that document the content of the subtopic."
          },
          "concept_bank": {
            "type": "array",
            "items": {
              "$ref": "#/$defs/concept"
            },
            "description": "A collection of concepts related to the subtopic."
          }
        },
        "description": "A subtopic that contains lessons on a specific aspect of the main topic.",
        "additionalProperties": false
      }
    },
    "required": [
      "topic"
    ],
    "properties": {
      "topic": {
        "type": "object",
        "required": [
          "title",
          "overview",
          "subtopics",
          "review"
        ],
        "properties": {
          "title": {
            "type": "string",
            "description": "The title of the topic."
          },
          "review": {
            "$ref": "#/$defs/subtopic"
          },
          "overview": {
            "type": "array",
            "items": {
              "$ref": "#/$defs/slide"
            },
            "description": "An overview of the topic comprising slides."
          },
          "subtopics": {
            "type": "array",
            "items": {
              "$ref": "#/$defs/subtopic"
            },
            "description": "A list of subtopics under the main topic."
          }
        },
        "description": "The main topic of the study notes.",
        "additionalProperties": false
      }
    },
    "additionalProperties": false
  }
}